\title{The Escape Radius Theorem for the Quadratic Family:\\
Elementary Dynamics of $z \mapsto z^2 + c$}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
The Mandelbrot set $M$ is the set of complex parameters $c$ for which the orbit
of $0$ under the quadratic map $f_c(z) = z^2 + c$ remains bounded. We give a
complete, self-contained development of the elementary metric dynamics of this
recurrence, culminating in the classical \emph{escape-radius theorem}: if at any
stage an orbit reaches a point $z$ with $\norm{z} > 2$ while the parameter
satisfies $\norm{c} \le \norm{z}$, then the orbit diverges geometrically, obeying
the explicit lower bound $\norm{f_c^{\,n}(z)} \ge \norm{z}\,(\norm{z}-1)^n$. As
an immediate consequence, any parameter with $\norm{c} > 2$ escapes, so $M$ is
contained in the closed disk of radius $2$: $M \subseteq \overline{B}(0,2)$. The
single analytic ingredient is the reverse triangle inequality
$\norm{z^2 + c} \ge \norm{z}^2 - \norm{c}$; everything else is induction and
elementary estimation. We complement the containment result with two exact
membership computations, $0 \in M$ and $-1 \in M$, the latter exhibiting the
period-$2$ cycle at the center of the largest bulb. We close by relating the
framework to the number theory of the bulbs --- the correspondence between
rational internal angles $p/q$ and attracting cycles of period $q$ --- and
outline the theorems that build on the escape estimate.
\end{abstract}

\maketitle

\section{Introduction}

Complex dynamics studies the iteration of holomorphic maps of the complex plane.
The single most studied family is the \emph{quadratic family}
\[
  f_c(z) = z^2 + c, \qquad c \in \C,
\]
because every quadratic polynomial is conjugate to exactly one member of this
family, and because the family already exhibits the full richness of the theory.
The associated parameter object is the \emph{Mandelbrot set}
\[
  \Mset = \{\, c \in \C : \text{the orbit } 0, f_c(0), f_c^{2}(0), \dots
  \text{ is bounded} \,\}.
\]

Everything computational about $\Mset$ rests on one prior question: given a
parameter $c$, how can one prove an orbit escapes to infinity in finite time?
The answer is the \emph{escape-radius theorem}. It supplies a threshold --- the
value $2$ --- beyond which divergence is certain, converting an infinite limiting
question into a finite, checkable condition. It is the theoretical foundation of
every algorithm that renders the Mandelbrot set, and the first structural fact
about $\Mset$: that it is bounded, and in fact contained in a disk of radius $2$.

This paper presents the theorem and its proof in full, from first principles,
assuming only the norm structure of $\C$ and the (reverse) triangle inequality.

\section{Definitions and setup}

Throughout, $\norm{\cdot}$ denotes the complex modulus on $\C$, which is
multiplicative ($\norm{zw} = \norm{z}\,\norm{w}$, hence $\norm{z^2} = \norm{z}^2$)
and satisfies the triangle inequality.

\begin{definition}[Quadratic step]
For a parameter $c \in \C$, define the map $f_c : \C \to \C$ by
$f_c(z) = z^2 + c$.
\end{definition}

\begin{definition}[Critical orbit]
The \emph{orbit of $0$} under $f_c$ is the sequence $(z_n)_{n \ge 0}$ defined by
$z_0 = 0$ and $z_{n+1} = f_c(z_n) = z_n^2 + c$. Equivalently $z_n = f_c^{\,n}(0)$.
We call $0$ the \emph{critical point}, since it is the unique zero of $f_c'$; its
orbit governs the global dynamics.
\end{definition}

\begin{definition}[Bounded orbit]
A parameter $c$ has a \emph{bounded orbit} if there is a real bound $R$ with
$\norm{z_n} \le R$ for all $n \ge 0$.
\end{definition}

\begin{definition}[Mandelbrot set]
$\Mset = \{\, c \in \C : c \text{ has a bounded orbit} \,\}$.
\end{definition}

Two elementary identities anchor the recursion. First,
$z_1 = f_c(0) = 0^2 + c = c$, so \emph{the first iterate of the critical point is
the parameter itself}; this is the hinge connecting the abstract escape estimate
to the concrete set $\Mset$. Second, from stage $1$ onward the orbit is the
forward iteration of $f_c$ started at $c$: $z_{n+1} = f_c^{\,n}(c)$.

\section{The one-step lower bound}

\begin{lemma}[One-step lower bound]\label{lem:onestep}
For all $c, z \in \C$,
\[
  \norm{f_c(z)} = \norm{z^2 + c} \ge \norm{z}^2 - \norm{c}.
\]
\end{lemma}

\begin{proof}
The triangle inequality gives $\norm{(z^2 + c) - c} \le \norm{z^2 + c} +
\norm{c}$; the left side equals $\norm{z^2} = \norm{z}^2$. Rearranging yields
$\norm{z}^2 - \norm{c} \le \norm{z^2 + c}$.
\end{proof}

The multiplicative amplifier $z \mapsto z^2$ squares the magnitude exactly, while
the additive term $c$ can pull the result back toward the origin by no more than
$\norm{c}$.

\section{One-step growth past the escape radius}

\begin{lemma}[Strict growth]\label{lem:grow}
Suppose $\norm{z} > 2$ and $\norm{c} \le \norm{z}$. Then $\norm{z} < \norm{f_c(z)}$.
\end{lemma}

\begin{proof}
Write $r = \norm{z} > 2$. By Lemma~\ref{lem:onestep},
$\norm{f_c(z)} \ge r^2 - \norm{c} \ge r^2 - r = r(r-1)$. Since $r > 2$, we have
$r - 1 > 1$, so $r(r-1) > r = \norm{z}$.
\end{proof}

The hypotheses are \emph{self-reproducing}: after one step the new magnitude
exceeds $\norm{z} > 2$, hence still exceeds $2$; and it still dominates $\norm{c}$
because $\norm{c} \le \norm{z} < \norm{f_c(z)}$. This invariance is what makes
induction possible.

\section{Geometric escape}

\begin{theorem}[Geometric escape estimate]\label{thm:geo}
Suppose $\norm{z} > 2$ and $\norm{c} \le \norm{z}$. Then for every $n \ge 0$,
\[
  \norm{f_c^{\,n}(z)} \ge \norm{z}\,(\norm{z} - 1)^n.
\]
\end{theorem}

\begin{proof}
Induct on $n$. For $n = 0$ the claim is $\norm{z} \le \norm{z}$. Assume the bound
for $n$; set $w = f_c^{\,n}(z)$. By the inductive hypothesis and $\norm{z}-1 > 1$,
$\norm{w} \ge \norm{z}(\norm{z}-1)^n \ge \norm{z}$, so $\norm{w} \ge \norm{z} > 2$
and $\norm{w} \ge \norm{c}$. Applying Lemma~\ref{lem:onestep} to $w$,
\[
  \norm{f_c^{\,n+1}(z)} = \norm{f_c(w)} \ge \norm{w}^2 - \norm{c}
  \ge \norm{w}^2 - \norm{w} = \norm{w}(\norm{w} - 1).
\]
Since $\norm{w} \ge \norm{z}(\norm{z}-1)^n$ and $\norm{w} - 1 \ge \norm{z} - 1$,
\[
  \norm{w}(\norm{w}-1) \ge \norm{z}(\norm{z}-1)^n (\norm{z}-1)
  = \norm{z}(\norm{z}-1)^{n+1}. \qedhere
\]
\end{proof}

\begin{corollary}[Unbounded orbit]\label{cor:unbdd}
Under the hypotheses of Theorem~\ref{thm:geo}, the sequence
$(\norm{f_c^{\,n}(z)})_{n\ge0}$ is unbounded: for every $R \in \R$ there is an
$n$ with $\norm{f_c^{\,n}(z)} > R$.
\end{corollary}

\begin{proof}
Since $\norm{z} - 1 > 1$, the geometric sequence $n \mapsto \norm{z}(\norm{z}-1)^n$
tends to $+\infty$; by Theorem~\ref{thm:geo} the orbit norms dominate it.
\end{proof}

\section{The escape criterion and containment}

\begin{theorem}[Escape criterion]\label{thm:escape}
If $\norm{c} > 2$, then the orbit of $0$ under $f_c$ is unbounded; consequently
$c \notin \Mset$.
\end{theorem}

\begin{proof}
The orbit reaches $z_1 = c$, with $\norm{c} > 2$ and $\norm{c} \le \norm{c}$.
Apply Corollary~\ref{cor:unbdd} with $z = c$: the iterates $f_c^{\,n}(c) = z_{n+1}$
are unbounded, so no uniform bound holds and $c \notin \Mset$.
\end{proof}

\begin{theorem}[Escape-radius theorem / containment]\label{thm:contain}
Every parameter of the Mandelbrot set satisfies $\norm{c} \le 2$. Equivalently,
\[
  \Mset \subseteq \overline{B}(0,2) = \{\, c \in \C : \norm{c} \le 2 \,\}.
\]
\end{theorem}

\begin{proof}
Contrapositive of Theorem~\ref{thm:escape}: if $\norm{c} > 2$ then
$c \notin \Mset$. Hence $c \in \Mset$ forces $\norm{c} \le 2$.
\end{proof}

The bound $2$ is sharp: $c = -2$ lies in $\Mset$ (its critical orbit is
$0 \to -2 \to 2 \to 2 \to \cdots$, bounded), and $\norm{-2} = 2$.

\section{Exact membership examples}

\begin{proposition}[$0 \in \Mset$]
The parameter $c = 0$ lies in $\Mset$.
\end{proposition}

\begin{proof}
For $c = 0$ the recurrence is $z_{n+1} = z_n^2$ with $z_0 = 0$, so $z_n = 0$ for
all $n$; the orbit is bounded by $R = 0$.
\end{proof}

\begin{proposition}[$-1 \in \Mset$; the period-2 cycle]\label{prop:negone}
The parameter $c = -1$ lies in $\Mset$, with critical orbit the $2$-cycle
$0 \to -1 \to 0 \to -1 \to \cdots$.
\end{proposition}

\begin{proof}
With $c = -1$: $z_0 = 0$, $z_1 = -1$, $z_2 = 0$, and the pattern repeats with
period $2$. A two-line induction shows $z_n \in \{0, -1\}$, whence
$\norm{z_n} \le 1$ for all $n$; the orbit is bounded by $R = 1$.
\end{proof}

The point $c = -1$ is the center of the largest bulb attached to the main
cardioid: the period-2 bulb.

\section{The number theory of the bulbs}

The main cardioid of $\Mset$ is the locus of parameters $c$ for which $f_c$ has an
attracting fixed point; it is parametrized by
\[
  c = \frac{\mu}{2} - \frac{\mu^2}{4}, \qquad |\mu| \le 1,
\]
where $\mu = f_c'(\text{fixed point})$ is the multiplier. On the boundary circle
$|\mu| = 1$, writing $\mu = e^{2\pi i\, p/q}$ with $p/q \in \Q$ in lowest terms, a
bulb of period $q$ is born by a parabolic bifurcation. Thus \emph{each bulb
corresponds to a rational $p/q$}: the internal angle $p/q$ selects where on the
cardioid the bulb attaches, and $q$ is the period of the attracting cycle inside
it. The largest bulb, at angle $1/2$ (multiplier $\mu = -1$), is the period-2
bulb centered at $c = -1$, matching Proposition~\ref{prop:negone}. The Farey
arrangement of these fractions around the cardioid encodes how the bulbs are
ordered --- number theory written into the geometry of the fractal. The
escape-radius theorem guarantees the arena (the disk of radius $2$) inside which
all of this structure lives.

\section{Algorithmic significance}

The escape-radius theorem justifies the standard \emph{escape-time algorithm}.
For each pixel $c$, iterate the recurrence and monitor $\norm{z_n}$. The moment
$\norm{z_n} > 2$, Theorem~\ref{thm:escape} guarantees divergence, so iteration
halts and reports the escape time $n$ (driving the coloring). If an iteration cap
is reached with $\norm{z_n} \le 2$, the pixel is provisionally classified as in
$\Mset$. Correctness of the escape branch is Theorem~\ref{thm:escape};
containment (Theorem~\ref{thm:contain}) guarantees the whole set fits in a fixed
viewport of radius $2$. Theorem~\ref{thm:geo} quantifies convergence: past the
threshold the norm multiplies by at least $\norm{z} - 1 > 1$ per step, so escape
is detected within a few extra iterations.

\section{Discussion and future work}

Building on these elementary results, natural next theorems include:
\begin{enumerate}
  \item \textbf{Sharper escape criterion:} trigger escape from any stage $z_n$
  with $\norm{z_n} > \max(\norm{c}, 2)$, not only from $z_1 = c$.
  \item \textbf{Compactness of $\Mset$:} combine containment with closedness
  ($\Mset$ is a countable intersection of closed conditions $\norm{z_n} \le 2$).
  \item \textbf{The real spine $[-2, 1/4] \subseteq \Mset \cap \R$:} the real
  orbit is trapped in an invariant interval around the attracting fixed point.
  \item \textbf{The main cardioid:} $c \in \Mset$ whenever $f_c$ has an
  attracting or neutral fixed point, giving $c = \mu/2 - \mu^2/4$, $|\mu| \le 1$.
  \item \textbf{Period-$q$ bulbs and rationals $p/q$:} establish the
  correspondence via the theory of parabolic bifurcations.
  \item \textbf{Connectedness of $\Mset$ (Douady--Hubbard):} the escape estimate
  is the first input to the potential-theoretic proof.
\end{enumerate}

\section{Conclusion}

From the single inequality $\norm{z^2 + c} \ge \norm{z}^2 - \norm{c}$ we derived,
by elementary induction, that any orbit exceeding magnitude $2$ (with the
parameter no larger) diverges geometrically, and therefore that the Mandelbrot
set is confined to the closed disk of radius $2$. Two exact computations placed
the origin and the period-2 center $-1$ inside the set. The most intricate object
in elementary mathematics is fenced in by the most basic estimate in analysis.

\end{document}

