function ESCAPE_TIME(c, max_iter, R = 2):
    z <- 0
    for n from 1 to max_iter:
        z <- z*z + c
        if |z| > R:
            return n            # orbit provably diverges
    return NONE                 # provisional member of M

function MEMBERSHIP_GRID(x_range, y_range, nx, ny, max_iter):
    for each cell (i, j):
        c <- sample(x_range, y_range, i, j)
        grid[j][i] <- ESCAPE_TIME(c, max_iter)  # NONE => in M
    return grid
